package com.securelock.app;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;
public class LockActivity extends Activity {private EditText pin;private TextView msg;private long blockedUntil=0;
 public static void requestLaunch(Context c,String reason){Intent i=new Intent(c,LockActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);try{c.startActivity(i);SecureLockPrefs.event(c,"Lock activity launch requested: "+reason);}catch(Exception e){SecureLockPrefs.event(c,"Lock launch blocked: "+e.getClass().getSimpleName());}}
 @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER);l.setPadding(36,36,36,36);l.setBackgroundColor(Color.rgb(7,13,24));TextView t=new TextView(this);t.setText("SecureLock");t.setTextSize(30);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);l.addView(t);TextView s=new TextView(this);s.setText("Enter your SecureLock PIN");s.setTextColor(Color.LTGRAY);s.setGravity(Gravity.CENTER);l.addView(s);pin=new EditText(this);pin.setInputType(2);pin.setHint("6–12 digit PIN");pin.setGravity(Gravity.CENTER);pin.setTextColor(Color.WHITE);l.addView(pin,new LinearLayout.LayoutParams(-1,-2));Button btt=new Button(this);btt.setText("Unlock SecureLock");btt.setOnClickListener(v->verify());l.addView(btt);msg=new TextView(this);msg.setTextColor(Color.LTGRAY);msg.setGravity(Gravity.CENTER);l.addView(msg);setContentView(l);}
 private void verify(){if(System.currentTimeMillis()<blockedUntil){msg.setText("Please wait before trying again.");return;}if(SecureLockPrefs.verifyPin(this,pin.getText().toString())){SecureLockPrefs.resetFailures(this);SecureLockPrefs.event(this,"SecureLock PIN accepted");finish();return;}int n=SecureLockPrefs.fail(this);pin.setText("");if(n>=5){blockedUntil=System.currentTimeMillis()+30000;new CountDownTimer(30000,1000){public void onTick(long m){msg.setText("Try again in "+((m+999)/1000)+" seconds");}public void onFinish(){msg.setText("You may try again");}}.start();}else msg.setText("Incorrect PIN. Attempt "+n);SecureLockPrefs.event(this,"Incorrect PIN attempt");}
 @Override public void onBackPressed(){} }
